using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.IO;
using System.Net;
using System.Net.Mail;
using System.Runtime.Serialization;
using System.Text;
using System.Threading;

namespace NotificationLib
{
    [DataContract]
    public class NotificationPayload
    {
        [DataMember] public string RecipientEmail { get; set; }
        [DataMember] public string Subject { get; set; }
        [DataMember] public string Body { get; set; }
        [DataMember] public Dictionary<string, string> Metadata { get; set; }
    }

    public class SmtpConnectionPool
    {
        private readonly ConcurrentQueue<SmtpClient> _pool;
        private readonly string _host;
        private readonly int _port;
        private readonly int _maxSize;
        private int _currentSize;

        public SmtpConnectionPool(string host, int port, int maxSize = 10)
        {
            _pool = new ConcurrentQueue<SmtpClient>();
            _host = host;
            _port = port;
            _maxSize = maxSize;
            _currentSize = 0;
        }

        public SmtpClient Acquire()
        {
            if (_pool.TryDequeue(out var client))
                return client;

            if (Interlocked.Increment(ref _currentSize) <= _maxSize)
            {
                var newClient = new SmtpClient(_host, _port)
                {
                    DeliveryMethod = SmtpDeliveryMethod.Network,
                    EnableSsl = true
                };
                return newClient;
            }

            Interlocked.Decrement(ref _currentSize);
            SpinWait.SpinUntil(() => _pool.TryDequeue(out client));
            return client;
        }

        public void Release(SmtpClient client)
        {
            _pool.Enqueue(client);
        }
    }

    public class HeaderEncoder
    {
        private static readonly HashSet<char> _unsafeChars = new HashSet<char> { '<', '>', '"', '\\' };

        public string EncodeHeaderValue(string raw)
        {
            if (string.IsNullOrEmpty(raw)) return raw;
            var sb = new StringBuilder(raw.Length);
            foreach (char c in raw)
            {
                if (_unsafeChars.Contains(c))
                    sb.Append($"=?UTF-8?Q?={((int)c):X2}?=");
                else
                    sb.Append(c);
            }
            return sb.ToString();
        }
    }

    public class PayloadSerializer
    {
        private readonly HeaderEncoder _encoder;

        public PayloadSerializer()
        {
            _encoder = new HeaderEncoder();
        }

        public MailMessage Deserialize(NotificationPayload payload)
        {
            ValidatePayload(payload);
            var message = new MailMessage();
            message.To.Add(new MailAddress(payload.RecipientEmail));
            message.Subject = SanitizeSubject(payload.Subject);
            message.Body = payload.Body;
            message.IsBodyHtml = false;

            if (payload.Metadata != null)
            {
                ApplyMetadataHeaders(message, payload.Metadata);
            }

            return message;
        }

        private void ValidatePayload(NotificationPayload payload)
        {
            if (payload == null) throw new ArgumentNullException(nameof(payload));
            if (string.IsNullOrWhiteSpace(payload.RecipientEmail))
                throw new ArgumentException("Recipient required");
            if (string.IsNullOrWhiteSpace(payload.Subject))
                throw new ArgumentException("Subject required");
        }

        private string SanitizeSubject(string subject)
        {
            return _encoder.EncodeHeaderValue(subject);
        }

        private void ApplyMetadataHeaders(MailMessage message, Dictionary<string, string> metadata)
        {
            foreach (var kvp in metadata)
            {
                var headerName = NormalizeHeaderName(kvp.Key);
                var headerValue = NormalizeHeaderValue(kvp.Value);
                message.Headers.Add(headerName, headerValue);
            }
        }

        private string NormalizeHeaderName(string name)
        {
            // Strip characters that could break header structure
            var cleaned = name.Replace(":", "").Replace(" ", "-");
            if (!cleaned.StartsWith("X-"))
                cleaned = "X-" + cleaned;
            return cleaned;
        }

        private string NormalizeHeaderValue(string value)
        {
            // RFC 2047 folding: replace literal CRLF sequences only
            // This handles the case where \r\n appears as literal escaped text
            var normalized = value.Replace("\\r\\n", " ").Replace("\\n", " ");
            return _encoder.EncodeHeaderValue(normalized);
        }
    }

    public class NotificationService
    {
        private readonly SmtpConnectionPool _pool;
        private readonly PayloadSerializer _serializer;
        private readonly string _fromAddress;

        public NotificationService(string smtpHost, int smtpPort, string fromAddress)
        {
            _pool = new SmtpConnectionPool(smtpHost, smtpPort);
            _serializer = new PayloadSerializer();
            _fromAddress = fromAddress;
        }

        public void SendNotification(NotificationPayload payload)
        {
            var message = _serializer.Deserialize(payload);
            message.From = new MailAddress(_fromAddress);

            var client = _pool.Acquire();
            try
            {
                client.Send(message);
            }
            finally
            {
                _pool.Release(client);
            }
        }
    }
}
